<!doctype html>
<html lang="id">
<head>
    <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
    <title>{{ $title ?? 'Admin' }} — Anime Event Organizer</title>
    <link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Outfit:wght@500;600;700;800&family=Plus+Jakarta+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@500;600&display=swap" rel="stylesheet">
    <style>
        :root{font-family:'Plus Jakarta Sans',sans-serif;color:#2c221e;background:#fff9f3;--orange:#f4511e;--terracotta:#a9361f;--ink:#2c221e;--muted:#756861;--line:#eadfd6;--surface:#fffdf9;--success:#287a54;--warning:#9a6700;--error:#b33d38}*{box-sizing:border-box}body{margin:0;min-height:100dvh}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}button{cursor:pointer}.shell{display:flex;min-height:100dvh}.rail{width:244px;flex:0 0 244px;padding:28px 18px;background:var(--terracotta);color:#fff3eb}.brand{display:inline-block;margin:0 12px 42px;font-family:Outfit,sans-serif;font-size:1.22rem;font-weight:800;letter-spacing:-.04em;color:#fff9f3}.brand span{color:#ffb18f}.nav-label{margin:0 12px 8px;color:#efb4a3;font-size:.68rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.nav{display:grid;gap:4px}.nav a{padding:11px 12px;border-radius:7px;color:#f5d8cd;font-size:.88rem;transition:background .2s cubic-bezier(.16,1,.3,1),color .2s cubic-bezier(.16,1,.3,1)}.nav a:hover,.nav a.active{background:#762817;color:#fff9f3}.logout{margin:32px 12px 0;padding:0;border:0;background:none;color:#efb4a3;font-size:.84rem}.menu-toggle{display:none}.page{min-width:0;flex:1;padding:36px clamp(20px,5vw,68px)}.page-inner{max-width:1180px;margin:auto}.topbar{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:30px}.eyebrow{margin:0 0 6px;color:var(--muted);font-size:.76rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase}h1,h2,h3{font-family:Outfit,sans-serif;letter-spacing:-.035em}h1{margin:0;font-size:clamp(1.8rem,4vw,2.8rem);line-height:1.05}h2{margin:0 0 6px;font-size:1.35rem}h3{margin:0;font-size:1rem}.lede{max-width:65ch;margin:9px 0 0;color:var(--muted);font-size:.92rem;line-height:1.6}.button{display:inline-flex;align-items:center;justify-content:center;min-height:44px;border:1px solid transparent;border-radius:7px;padding:10px 15px;background:var(--orange);color:#fff9f3;font-weight:700;transition:background .2s cubic-bezier(.16,1,.3,1),transform .2s cubic-bezier(.16,1,.3,1)}.button:hover{background:#d94317;transform:translateY(-1px)}.button.secondary{border-color:var(--line);background:transparent;color:var(--ink)}.button.secondary:hover{background:#fff0e9}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.stat{padding:18px 20px 18px 0;border-right:1px solid var(--line)}.stat:not(:first-child){padding-left:20px}.stat:last-child{border-right:0}.stat-label{color:var(--muted);font-size:.78rem}.stat-value{margin-top:7px;font-family:'JetBrains Mono',monospace;font-size:1.45rem;font-weight:600;font-variant-numeric:tabular-nums}.section{margin-top:30px}.panel{border:1px solid var(--line);background:var(--surface);box-shadow:0 16px 36px rgba(118,40,23,.08)}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 20px;border-bottom:1px solid var(--line)}.panel-body{padding:20px}.table-wrap{overflow-x:auto}.table{width:100%;border-collapse:collapse;min-width:640px}.table th,.table td{padding:14px 18px;text-align:left;border-bottom:1px solid var(--line);font-size:.84rem;vertical-align:middle}.table th{color:var(--muted);font-size:.7rem;letter-spacing:.08em;text-transform:uppercase}.table tr:last-child td{border-bottom:0}.table tr:hover td{background:#fff5ed}.mono{font-family:'JetBrains Mono',monospace;font-size:.8rem}.badge{display:inline-flex;border-radius:999px;padding:5px 9px;font-size:.7rem;font-weight:700}.badge.success{background:#e4f2e9;color:var(--success)}.badge.warning{background:#fff3d6;color:var(--warning)}.badge.error{background:#fbe8e6;color:var(--error)}.badge.neutral{background:#f1ebe5;color:var(--muted)}.empty{padding:36px 20px;text-align:center;color:var(--muted)}.empty strong{display:block;margin-bottom:5px;color:var(--ink);font-family:Outfit,sans-serif;font-size:1.05rem}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.field{display:grid;gap:7px}.field.full{grid-column:1/-1}.field label{font-size:.82rem;font-weight:700}.field input,.field select,.field textarea{width:100%;border:1px solid var(--line);border-radius:7px;padding:11px 12px;background:#fff9f3;color:var(--ink)}.field textarea{min-height:120px;resize:vertical}.field input:focus,.field select:focus,.field textarea:focus{outline:2px solid #f7b49f;outline-offset:1px;border-color:var(--orange)}.field small{color:var(--muted);font-size:.75rem}.alert{margin-bottom:20px;padding:12px 14px;border:1px solid #efc7c2;border-radius:7px;background:#fff3f1;color:var(--error);font-size:.84rem}.actions{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}:focus-visible{outline:2px solid var(--orange);outline-offset:3px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:900px) and (min-width:561px){.rail{width:220px;flex-basis:220px}}@media(max-width:560px){.shell{display:block}.rail{width:auto;padding:14px 16px}.brand{margin:0 0 10px;font-size:1.05rem}.nav-label{display:none}.menu-toggle{display:grid;place-items:center;width:44px;height:44px;margin-left:auto;border:0;background:transparent;color:#fff9f3}.menu-toggle svg{width:24px;height:24px}.menu-toggle svg path{stroke-width:3;stroke-linecap:round}.nav{display:none;margin-top:8px}.rail.menu-open .nav{display:grid}.rail.menu-open .logout{display:block;margin-top:14px}.nav a{font-size:.8rem;text-align:left}.page{padding:28px 16px}.topbar{align-items:flex-start;flex-direction:column}.stats{grid-template-columns:1fr 1fr}.stat,.stat:not(:first-child){padding:14px 12px}.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}.actions{justify-content:stretch;flex-direction:column}.actions .button{width:100%}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;transition-duration:.01ms!important;animation-duration:.01ms!important}}
        @media(max-width:560px){.rail{display:flex;flex-wrap:wrap;align-items:center}.rail .menu-toggle{order:1;margin:0 12px 0 0}.rail .brand{order:2;margin:0}.rail .nav-label{order:3;width:100%}.rail .nav{order:4;width:100%}.rail .logout{order:5;display:none}.rail.menu-open .logout{display:block}}
    </style>
</head>
<body>
<div class="shell"><aside class="rail" id="admin-rail"><a class="brand" href="{{ url('/admin/dashboard') }}">ANIME <span>EVENT</span></a><button class="menu-toggle" type="button" aria-controls="admin-nav" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg><span class="sr-only">Buka menu navigasi</span></button><p class="nav-label">Workspace</p><nav class="nav" id="admin-nav" aria-label="Navigasi admin"><a class="{{ request()->is('admin/dashboard') ? 'active' : '' }}" href="{{ url('/admin/dashboard') }}">Dashboard</a><a class="{{ request()->is('admin/events*') ? 'active' : '' }}" href="{{ url('/admin/events') }}">Events</a><a class="{{ request()->is('admin/vendor*') ? 'active' : '' }}" href="{{ url('/admin/vendor') }}">Vendors</a><a class="{{ request()->is('admin/customers*') ? 'active' : '' }}" href="{{ url('/admin/customers') }}">Customers</a><a class="{{ request()->is('admin/bookings*') ? 'active' : '' }}" href="{{ url('/admin/bookings') }}">Bookings</a><a class="{{ request()->is('admin/tickets*') ? 'active' : '' }}" href="{{ url('/admin/tickets') }}">Tickets</a><a class="{{ request()->is('admin/categories*') ? 'active' : '' }}" href="{{ url('/admin/categories') }}">Categories</a></nav><button class="logout" type="button">Sign out</button></aside><main class="page"><div class="page-inner">@if (session('success'))<div class="alert" style="color:var(--success);border-color:#b9ddc7;background:#eef9f1" role="status">{{ session('success') }}</div>@endif @yield('content')</div></main></div>
<script>const toggle=document.querySelector('.menu-toggle');const rail=document.getElementById('admin-rail');toggle?.addEventListener('click',()=>{const open=rail.classList.toggle('menu-open');toggle.setAttribute('aria-expanded',open);toggle.querySelector('.sr-only').textContent=open?'Tutup menu navigasi':'Buka menu navigasi';});</script>
</body>
</html>
